const e={title:"TripReel - Application d'Animation de Voyage Gratuite : Transformez vos Photos en Vidéos Magnifiques",description:"Créez des vidéos de voyage époustouflantes avec des cartes animées et des itinéraires de vol. Application d'animation de voyage gratuite avec cartographie de route en globe 3D. Transformez vos photos en belles vidéos de voyage automatiquement. Confidentialité d'abord, fonctionne hors ligne.",keywords:"application d'animation de voyage, application d'animation de carte de voyage, application d'animation d'itinéraire de voyage, application d'animation de vol, créateur de vidéo de voyage, vidéo de voyage automatique, carte de voyage animée, animation d'itinéraire de vol, animation de voyage, animation de globe, vidéo de récapitulatif de voyage, photo en vidéo, temps forts de voyage, application de voyage gratuite, créateur de vidéo hors ligne, application de voyage confidentielle, vidéo de pellicule"},i={logoAlt:"Logo TripReel",appName:"TripReel",howItWorks:"Comment ça marche",video:"Vidéo",features:"Fonctionnalités",theApp:"L'application"},t={badge:"Transformez vos photos en récits de voyage",title1:"Votre pellicule,",title2:"pleinement exploitée",description:"TripReel crée automatiquement de magnifiques vidéos de voyage à partir des localisations de vos photos. Regardez vos voyages prendre vie avec de superbes cartes de parcours animées et des trajectoires de vol sur un globe 3D, tout en gardant vos données privées et sécurisées.",secure:"100% sécurisé",worksOffline:"Fonctionne hors ligne",globeAlt:"Animation du globe TripReel"},o={title:"Comment ça marche",subtitle:"Trois étapes simples pour créer votre vidéo de voyage parfaite",step1:{title:"Autorisez l'accès aux photos",description:"Accordez à TripReel l'accès à votre photothèque. L'application lit uniquement les métadonnées de localisation, rien d'autre."},step2:{title:"Détection automatique des voyages",description:"TripReel analyse les métadonnées de localisation et identifie intelligemment vos voyages selon les dates et les lieux."},step3:{title:"Générez votre vidéo",description:"Regardez votre voyage se dérouler sur une magnifique animation de globe, prête à partager sur les réseaux sociaux."}},s={title:"Découvrez la magie en action",subtitle:"Voyez comment TripReel transforme votre photothèque en vidéos de voyage extraordinaires",caption:"Voici à quoi peut ressembler votre vidéo de voyage finale"},a={title:"Tout ce dont vous avez besoin",subtitle:"Des fonctionnalités puissantes conçues pour les voyageurs modernes",twoTap:{title:"Vidéos de voyage en deux clics",description:"Créez de superbes vidéos de voyage depuis votre photothèque en seulement deux clics. Aucun montage nécessaire."},smartTrip:{title:"Détection intelligente des voyages",description:"Trouve et regroupe automatiquement vos voyages en analysant les dates et les métadonnées de localisation de vos photos."},globe:{title:"Magnifique animation de globe",description:"Regardez votre voyage prendre vie avec un superbe globe 3D montrant vos itinéraires de voyage animés et vos trajectoires de vol à travers le monde."},privacy:{title:"Confidentialité d'abord",description:"Tout se traite sur votre appareil. Vos photos ne quittent jamais votre téléphone. Fonctionne en mode avion."},customStyles:{title:"Styles personnalisés",description:"Choisissez parmi plusieurs styles de globe et personnalisations pour correspondre à votre esthétique et rendre chaque vidéo unique."},manualControl:{title:"Contrôle manuel",description:"Vous pouvez ajouter manuellement de nouveaux voyages si les services de localisation n'étaient pas activés sur votre appareil."}},n={title:"Idées de vidéos créatives",subtitle:"Inspirez-vous de ce que vous pouvez créer avec TripReel. Des escapades de week-end rapides aux aventures d'un an, créez de superbes vidéos de voyage pour chaque périple.",description:"Que vous créiez une animation de carte de voyage, documentiez un itinéraire de vol ou réalisiez un récapitulatif annuel de vos voyages, TripReel facilite la transformation de vos souvenirs en vidéos partageables.",ideas:{yearRecap:{title:"Récap voyages 2025",description:"Créez automatiquement votre récapitulatif annuel de voyages 2025"},europeRoadTrip:{title:"Road trip européen",description:"Présentez votre aventure européenne avec des cartes de parcours animées"},southeastAsia:{title:"Voyage en Asie du Sud-Est",description:"Visualisez votre parcours de routard à travers plusieurs pays"},japanRail:{title:"Voyage en train au Japon",description:"Créez des vidéos cartographiques de vos itinéraires en train au Japon"},crossCountry:{title:"Traversée des États-Unis",description:"Transformez votre road trip américain en vidéo d'itinéraire épique"},islandHopping:{title:"Tour des îles",description:"Montrez vos voyages d'île en île avec de superbes animations 3D"},worldTour:{title:"Montage tour du monde",description:"Plusieurs voyages en une seule vidéo de voyage mondiale extraordinaire"},travelPlans:{title:"Projets de voyage 2026",description:"Visualisez et planifiez vos aventures de voyage passionnantes pour 2026"},lifetimeTravel:{title:"Histoire de voyage d'une vie",description:"Créez une vidéo présentant tous vos voyages de toute une vie"},regionalExplorer:{title:"Explorateur régional",description:"Cartographiez vos aventures à travers États, provinces et régions"},festivalCircuit:{title:"Circuit des festivals",description:"Tracez votre parcours de festivals de musique et d'événements"},bikeRoutes:{title:"Mes escapades urbaines",description:"Présentez toutes vos escapades citadines"}}},r={title:"L'application",subtitle:"Disponible maintenant sur l'App Store",alt1:"Vidéos de voyage automatiques - Créez de superbes vidéos en quelques secondes",alt2:"Détection de localisation des photos - Utilise les métadonnées de vos photos",alt3:"Détection des voyages - Regroupe automatiquement vos voyages",alt4:"Magnifiques vidéos de globe - Animation de globe de votre voyage",alt5:"Styles personnalisés - Personnalisez vos vidéos de voyage"},l={comingSoon:"Bientôt disponible",androidTitle:"Application Android bientôt disponible !",androidMessage:'La version Android n\'est pas encore disponible mais le sera bientôt. Envoyez-moi un message à <a href="mailto:marian@qod.ee?subject=TripReel%20Android%20App" class="text-sky-600 dark:text-sky-400 hover:text-sky-700 dark:hover:text-sky-300 font-semibold transition-colors">marian@qod.ee</a> et je vous tiendrai informé dès qu\'elle sera prête !',gotIt:"Compris !"},u={title:"Questions fréquentes",subtitle:"Tout ce que vous devez savoir sur TripReel",q1:{question:"Puis-je vraiment utiliser l'application entièrement en mode avion ?",answer:"Oui ! Pour les utilisateurs premium, l'application peut être utilisée complètement hors ligne en mode avion sans aucune limitation. Pour les utilisateurs non-premium, certaines fonctionnalités sont financées par la publicité et peuvent nécessiter d'activer temporairement Internet, mais pour les utilisateurs premium il n'y a pas de publicités et l'application peut être entièrement utilisée en mode avion."},q2:{question:"J'ai passé à Premium, comment puis-je retirer le filigrane ?",answer:"Beaucoup de personnes demandent quelle application a été utilisée pour créer ces vidéos, donc après avoir passé à premium, vous avez l'option d'ajouter une version plus petite du filigrane (avec juste le nom de l'application) ou de le retirer complètement si vous le souhaitez."},q3:{question:"Mes données photo sont-elles sûres et privées ?",answer:"Absolument ! TripReel lit uniquement les métadonnées de localisation de vos photos - nous n'accédons jamais, ne stockons jamais ni ne transmettons jamais le contenu réel de vos photos. Tout le traitement se fait localement sur votre appareil, et aucune donnée ne quitte jamais votre téléphone. Vous pouvez le vérifier en utilisant l'application en mode avion - elle fonctionne parfaitement hors ligne !"},q4:{question:"Que faire si mes photos n'ont pas de données de localisation ?",answer:"Pas de problème ! Si les services de localisation n'étaient pas activés lorsque vous avez pris vos photos, vous pouvez créer manuellement des voyages et ajouter vous-même les localisations. L'application vous donne un contrôle total pour personnaliser votre chronologie de voyage."},q5:{question:"Comment l'application détecte-t-elle mes voyages automatiquement ?",answer:"TripReel analyse les métadonnées de localisation et les horodatages de vos photos pour identifier intelligemment quand et où vous avez voyagé. Elle regroupe les localisations et dates proches pour détecter automatiquement vos voyages sans aucun travail manuel."},q6:{question:"Puis-je personnaliser l'apparence de mes vidéos ?",answer:"Oui ! Vous pouvez choisir parmi plusieurs styles de globe et personnaliser divers aspects de vos vidéos de voyage animées pour correspondre à votre esthétique personnelle. Les utilisateurs premium ont accès à des styles d'animation de parcours supplémentaires, des thèmes de cartes et des options de trajectoires de vol."},q7:{question:"Dois-je créer un compte ?",answer:"Aucun compte requis ! TripReel fonctionne immédiatement après le téléchargement. Pas d'inscription, pas de connexion et aucune information personnelle nécessaire. Téléchargez simplement l'application et commencez à créer vos vidéos de voyage tout de suite."},q8:{question:"Pourquoi une localisation manque-t-elle dans mon voyage ?",answer:"L'application ne peut fonctionner qu'avec les données disponibles, donc tout d'abord vous avez besoin d'au moins quelques photos à cet endroit. Deuxièmement, vous devez vous assurer que les données de localisation étaient activées lorsque vous y étiez. Troisièmement, parfois une faible réception GPS peut causer des données de localisation incorrectes. Si vous avez éliminé tout cela et que votre localisation ne s'affiche toujours pas, vous pouvez ajouter manuellement cette localisation depuis Vue d'ensemble des voyages > bouton Modifier. Veuillez également utiliser Contact pour signaler le problème."},q9:{question:"Où puis-je partager ma superbe vidéo ?",answer:"Bien sûr, vous pouvez aussi la partager sur toutes les plateformes sociales. Pour mieux s'adapter à la plateforme, l'application permet différents formats d'image pour vos vidéos."},q10:{question:"Où puis-je signaler un bug ?",answer:"Contactez-moi directement à marian@qod.ee en expliquant brièvement quel est le problème."}},d={title:"Assistance par email",description:"Si vous avez des commentaires ou rencontrez des problèmes, n'hésitez pas à me contacter directement à cette adresse email et je lirai et traiterai personnellement votre demande aussi rapidement que possible. Merci d'utiliser l'application !",close:"Fermer"},p={default:{title:"🍪 Cookies",message:"Nous utilisons des cookies sur le site TripReel pour améliorer votre expérience. Aucune donnée personnelle collectée.",accept:"Accepter",decline:"Refuser",details:"Détails"},theme:{title:"🍪 Cookies",message:"🌙 Pour enregistrer votre préférence de thème, vous devez accepter les cookies essentiels sur le site TripReel. Sans eux, votre choix de thème ne peut pas être sauvegardé.",accept:"Accepter",decline:"Refuser",details:"Détails"}},c={privacy:"Politique de confidentialité de l'app",cookies:"Politique de cookies du site",contact:"Contact",cookiePreferences:"Préférences de cookies",madeWith:"Créé avec",forTravelers:"pour les voyageurs du monde entier",copyright:"© {{year}} TripReel."},v={title:"Prêt à partager votre voyage ?",description:"Téléchargez TripReel aujourd'hui et transformez votre pellicule en magnifiques vidéos de voyage avec des cartes et itinéraires animés. Vos aventures méritent d'être célébrées.",features:"Téléchargement gratuit • Rapide et pratique • Confidentialité garantie"},m={meta:e,header:i,hero:t,howItWorks:o,videoSection:s,features:a,videoIdeas:n,screenshots:r,appStore:l,faq:u,contact:d,cookieBanner:p,footer:c,cta:v};export{l as appStore,d as contact,p as cookieBanner,v as cta,m as default,u as faq,a as features,c as footer,i as header,t as hero,o as howItWorks,e as meta,r as screenshots,n as videoIdeas,s as videoSection};
